class cap():
   '''contains anything connected capturing (resolutions, tests, capturing...)'''
   def __init__(self, camera=None, resolution=None):

      self.maxdev = 7 # max number of devices to be tested
      self.test_res = [(1920,1080), (1280, 720), (960, 540), (848, 480), (640, 480)] # common webcam resolutions to test

      # paused image
      self.paused = False

      self.blank_rgb = [255, 255, 255]   # rgb-values for blanked screen (b key)
      self.blanked   = False          # (start with) showing a curtain instead of the captured image

      
      self.devices = self._detectdev()
      if camera is not None and camera not in self.devices:
         sys.exit('selected webcam /dev/video'+str(camera)+' not found')
      self.device = self.devices.index(camera) if camera is not None else 0
      self.resolutions = self._detectres(self.device)
      if resolution is not None:
         if resolution in self.resolutions:
            self.resolutions.remove(resolution)
         self.resolutions.insert(0, resolution)
      if not self.resolutions:
         sys.exit('no valid webcam resolution found')
      self.resolution = 0
      
      self._createstream() # start with highest resolution detected
   
   
   
   def _detectdev(self):
      # detect webcams
      res = []
      for i in range(0, self.maxdev):
         img = cv2.VideoCapture(i)
         if img.read()[0]:
            res.append(i)
         img.release()

      if not len(res) > 0:
         sys.exit('no webcam found')
      print("Webcams: ", res)
      return res
   
   def _detectres(self, dev):
      device = self.devices[dev]
      res = []
      v4l = shutil.which('v4l2-ctl')
      if not v4l == None:
         # get resolution information from video4linux
         v4lres = subprocess.check_output(v4l+' -d /dev/video'+str(device)+' --list-formats-ext | grep Size | cut -d " " -f 3 | sort | uniq', shell=True).splitlines()
         for r in v4lres:
            test = tuple( int(i) for i in r.decode().split('x'))
            res.append(test)
      else:
         # testing common resolutions
         test = imutils.video.WebcamVideoStream(src=device)  # threaded stream
         for x,y in self.test_res:
            works = False
            test.stream.set(3, x)
            test.stream.set(4, y)
            # test if SET resolutions are same as GET 
            if (int(test.stream.get(3)) == x and int(test.stream.get(4)) == y):
               works = True
            # another chance (worked for corvusalbus)
            elif (int(test.stream.get(cv2.CAP_PROP_FRAME_WIDTH)) == x and int(test.stream.get(cv2.CAP_PROP_FRAME_HEIGHT)) == y):
               works = True
            if works:
               res.append((x,y))
         test.stream.release()
      if len(res) == 0:
         # Fall back to the resolution currently supplied by the camera.
         test = cv2.VideoCapture(device)
         width = int(test.get(cv2.CAP_PROP_FRAME_WIDTH))
         height = int(test.get(cv2.CAP_PROP_FRAME_HEIGHT))
         test.release()
         if width > 0 and height > 0:
            res.append((width, height))
      res.sort(reverse=True)
      print("Auflösungen:", res)
      return res
   
   def _blank(self):
      img          = self.vs.read()           # no need for a picture here actually
      if img is None:
         sys.exit('webcam stopped providing images')
      self.res      = img.shape[1], img.shape[0]  # but this makes sure that the created
      self.ratio     = self.res[0]/self.res[1]    # frame always fits the captured image
      return np.uint8(np.absolute(self.blank_rgb * np.ones((self.res[1], self.res[0], 3), np.uint8)))
   
   def _capture(self):
      img          = self.vs.read()           # get single frame (for resolution and ratio)
      if img is None:
         sys.exit('webcam stopped providing images')
      self.res      = img.shape[1], img.shape[0]  # save resolution
      self.ratio     = self.res[0]/self.res[1]    # save ratio (for correct zoom)
      return img
   
   def pause(self):
      if not self.paused: # catch the pause image
         self.pause_img = self.vs.read()                             # get single frame (for resolution and ratio)
         if self.pause_img is None:
            sys.exit('webcam stopped providing images')
         self.res      = self.pause_img.shape[1], self.pause_img.shape[0]  # save resolution
         self.ratio     = self.res[0]/self.res[1]                      # save ratio (for correct zoom)
      self.paused    = not self.paused
   
   def toggleblank(self):
      self.blanked = not self.blanked
   
   def updateres(self, frame):
      h, w, _ = frame.shape
      self.res = w, h
   
   def get(self):
      if self.blanked:
         return self._blank()
      else:
         if self.paused:
            return self.pause_img
         else:
            return self._capture()
   
   def _createstream(self):
      self.vs = imutils.video.WebcamVideoStream(src=self.devices[self.device]) # threaded stream
      #self.vs.stream.set(cv2.CAP_PROP_FPS, 30.0)        # set FPS
      #self.vs.stream.set(cv2.CAP_PROP_FOURCC, 0x47504A4D) # set codec (MJPG) - PROVOKES SEGFAULT WHEN RELEASING STREAM
      res = self.resolutions[self.resolution]
      self.vs.stream.set(3, res[0])
      self.vs.stream.set(4, res[1])
      self.vs.start()

      started = time.time()
      while time.time() - started < 5:
         # wait until resolution is correct
         img = self.vs.read()
         if img is not None and img.shape[1] == res[0] and img.shape[0] == res[1]:
            return
         time.sleep(0.01)
      if img is not None:
         actual_res = img.shape[1], img.shape[0]
         self.resolutions[self.resolution] = actual_res
         print('Webcam-Auflösung abweichend:', actual_res)
         return
      self.vs.stop()
      sys.exit('webcam did not provide images')
   
   def resminus(self):
      if self.resolution < len(self.resolutions) - 1:
         self.vs.stream.release()
         #self.vs.stop()
         self.vs = None
         self.resolution += 1
         self._createstream()
         
   def nextdev(self):
      if not len(self.devices) == 1:
         self.vs.stop()
         self.vs.stream.release()
         
         c = False
         while not c:
            if self.device < len(self.devices)-1:
               self.device += 1
            else:
               self.device = 0
            self.resolutions = self._detectres(self.device)

            if len(self.resolutions) > 0:
               c = True

         self.resolution  = 0  # choose biggest resolution first
         self._createstream()
   
   def resplus(self):
      if self.resolution > 0:
         self.vs.stream.release()
         #self.vs.stop()
         self.vs = None
         self.resolution -= 1
         self._createstream()

class inp():
   '''state of the mouse'''
   def __init__(self):
      self.state = 0         # button state: 0 nothing/move unpressed, 1 pressed, 2 move pressed, 3 released
      self.pos   = (0, 0)     # position (relative to window)
      self.posa  = (0, 0)     # absolute position
      self.start = (0, 0)     # position, when pressed move started
      self.delta = (0, 0)     # mouse delta (for painting rectangles)
      self.key   = ''        # key that was pressed
      self.cmd   = ''        # placeholder for a command invoked by a key
      self.timer = time.time() # timer for popups
      
   def mouse_click(self, event):
      self.state = 1
      self.start = event.x, event.y
      self.pos = event.x, event.y
      self.delta = (0, 0)
      self.timer = time.time() # timer for tooltips
   def mouse_release(self, event):
      self.state = 3
      self.pos = event.x, event.y
      self.timer = time.time() # timer for tooltips
   def mouse_move(self,event):
      self.pos   = event.x, event.y
      if self.state == 1:
         self.state = 2
      if self.state == 2:
         self.delta = self.pos[0] - self.start[0], self.pos[1] - self.start[1]
      self.timer = time.time() # timer for tooltips
   def key_press(self, event):
      self.key = event.char
   def esc(self, event):
      self.key = 'esc'
   def left(self, event):
      self.key = 'left'
   def right(self, event):
      self.key = 'right'
   def up(self, event):
      self.key = 'up'
   def down(self, event):
      self.key = 'down'
   def wait(self):
      return (time.time() - self.timer)*10

class ocr():

   def ocrend(self, frame, i):
      if i.delta[0] != 0 and i.delta[1] != 0:
         # extract ocr area
         x1, x2 = sorted((i.start[0], i.start[0] + i.delta[0]))
         y1, y2 = sorted((i.start[1], i.start[1] + i.delta[1]))
         x1, x2 = max(0, x1), min(frame.shape[1], x2)
         y1, y2 = max(0, y1), min(frame.shape[0], y2)
         if x1 >= x2 or y1 >= y2:
            return
         ocr_img = frame[y1:y2, x1:x2]
         # do some image manipulations
         ocr_gray = cv2.cvtColor(ocr_img, cv2.COLOR_RGB2GRAY)
         ocr_gray, ocr_img_bin = cv2.threshold(ocr_gray,128,255,cv2.THRESH_BINARY | cv2.THRESH_OTSU)
         ocr_gray = cv2.bitwise_not(ocr_img_bin)
         ocr_kernel = np.ones((2, 1), np.uint8)
         ocr_img = cv2.erode(ocr_gray, ocr_kernel, iterations=1)
         ocr_img = cv2.dilate(ocr_img, ocr_kernel, iterations=1)
         # use pytesseract to detect the text
         ocr_txt = pytesseract.image_to_string(ocr_img)
         # use pyperclip to copy text to clipboard
         pyperclip.copy(ocr_txt)

class tune():
   '''apply different filter to the frame'''
   def __init__(self):
      self.rotation      = 0    # image rotation (0 no rotation, 1: 90°, 2: 180°, 3: 270°)
      self.flip         = set() # image flip set (may contain 'v'ertical, 'h'orizontal or both)
      
      self.brightness     = 0    # standard value for brightness
      self.brightnessstep  = 10   # brightness-delta
      self.contrast      = 255   # standard value for contrast
      self.contraststep   = 10
      self.colormode      = 0    # the actual color mode (0 color, 1 grey, 2 b/w)

   def brightminus(self):
      self.brightness -= self.brightnessstep
   def brightreset(self):
      self.brightness  = 0
   def brightplus(self):
      self.brightness += self.brightnessstep
   def contrastminus(self):
      self.contrast -= self.contraststep
   def contrastreset(self):
      self.contrast  = 255
   def contrastplus(self):
      self.contrast += self.contraststep
   def rotationminus(self):
      if self.rotation > 0:
         self.rotation -= 1
      else:
         self.rotation = 3
   def rotationreset(self):
      self.rotation = 0
   def rotationplus(self):
      if self.rotation < 3:
         self.rotation += 1
      else:
         self.rotation = 0
   def flipvertical(self):
      self.flip.remove('v') if 'v' in self.flip else self.flip.add('v')
   def flipboth(self):
      if 'v' in self.flip:
         self.flip.remove('v')
      else:
         self.flip.add('v')
      if 'h' in self.flip:
         self.flip.remove('h')
      else:
         self.flip.add('h')
   def fliphorizontal(self):
      if 'h' in self.flip:
         self.flip.remove('h')
      else:
         self.flip.add('h')
   def color0(self):
      self.colormode = 0
   def color1(self):
      self.colormode = 1
   def color2(self):
      self.colormode = 2

   def applyfliprotate(self, frame, c):
      # BASIC IMAGE MANUPULATION
      # flipping image
      if 'v' in self.flip and 'h' in self.flip:
         frame = cv2.flip(frame, -1)
      elif 'v' in self.flip:
         frame = cv2.flip(frame, 1)
      elif 'h' in self.flip:
         frame = cv2.flip(frame, 0)
      
      # adjust rotation (TODO: change zoom position?)
      if self.rotation == 0:
         #res_capc = res_cap
         pass
      elif self.rotation == 1:
         frame = cv2.rotate(frame, cv2.ROTATE_90_CLOCKWISE)
         c.res = c.res[1], c.res[0] # adjust capture resolution
      elif self.rotation == 2:
         frame = cv2.rotate(frame, cv2.ROTATE_180)
      elif self.rotation == 3:
         frame = cv2.rotate(frame, cv2.ROTATE_90_COUNTERCLOCKWISE)
         c.res = c.res[1], c.res[0] # adjust capture resolution
      return frame

   def applyother(self, frame):
      # adjust brightness and contrast
      b = self.brightness
      c = self.contrast
      alpha = b
      beta = b+c
      cv2.normalize(frame, frame, alpha, beta, cv2.NORM_MINMAX)

      # adjust color mode
      if self.colormode == 1:
         frame = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
         frame = cv2.cvtColor(frame, cv2.COLOR_GRAY2BGR)
      elif self.colormode == 2:
         gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
         (thresh, frame) = cv2.threshold(gray, 127, 255, cv2.THRESH_BINARY)
         frame = cv2.cvtColor(frame, cv2.COLOR_GRAY2BGR)
      
      return frame

